package com.ruoyi.web.controller.shop;
import java.util.*;import com.alibaba.fastjson2.*;import org.springframework.beans.factory.annotation.Autowired;import org.springframework.context.annotation.Lazy;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import static com.ruoyi.web.controller.shop.ShopService.*;
@Service public class ShopWarehouse {
 @Autowired @Lazy ShopService s;
 private void movement(long wid,long pid,String channel,String kind,long qty,String key,String note,String who){s.jdbc().update("insert into shop_warehouse_movement(warehouse_id,product_id,channel,kind,quantity,reference_key,note,operator_name) values(?,?,?,?,?,?,?,?)",wid,pid,channel,kind,qty,key,note,who);}
 private void cell(long wid,long pid,String channel){s.jdbc().update("insert ignore into shop_warehouse_stock(warehouse_id,product_id,channel) values(?,?,?)",wid,pid,channel);}
 @Transactional public void ensure(long pid){Map<String,Object> p=s.one("select * from shop_product where id=? for update",pid);if(s.jdbc().queryForObject("select count(*) from shop_warehouse_stock where product_id=?",Long.class,pid)>0)return;long amount=number(p.get("stock")),legacy=JSON.parseObject(str(s.one("select content from shop_config where config_key='warehouse-migration'").get("content"))).getLongValue("legacyMax"),b=pid<=legacy?amount/2:0;cell(1,pid,"C");cell(1,pid,"B");s.jdbc().update("update shop_warehouse_stock set available=? where warehouse_id=1 and product_id=? and channel='C'",amount-b,pid);s.jdbc().update("update shop_warehouse_stock set available=? where warehouse_id=1 and product_id=? and channel='B'",b,pid);movement(1,pid,"C","migration",amount-b,"initial","存量可售库存守恒迁入，历史商品零售与采购各分配一半（单件尾数归零售）","系统");if(b>0)movement(1,pid,"B","migration",b,"initial","存量采购可售分配，可由仓库调整","系统");
 for(Map<String,Object> i:s.jdbc().queryForList("select i.*,o.channel,o.status order_status,o.tracking order_tracking from shop_order_item i join shop_order o on o.id=i.order_id where i.product_id=? and o.status in ('pending','paid','shipping','shipped')",pid)){long qty=number(i.get("quantity")),oid=number(i.get("order_id")),item=number(i.get("id"));if("shipped".equals(i.get("order_status"))&&!str(i.get("order_tracking")).isEmpty()&&s.jdbc().queryForObject("select count(*) from shop_shipment where order_id=?",Long.class,oid)==0)qty=0;for(Map<String,Object> parcel:s.jdbc().queryForList("select items_json from shop_shipment where order_id=?",oid))for(Object obj:JSON.parseArray(str(parcel.get("items_json")))){JSONObject line=JSON.parseObject(JSON.toJSONString(obj));if(line.getLongValue("id")==item)qty-=line.getLongValue("quantity");}for(Map<String,Object> c:s.jdbc().queryForList("select items_json from shop_case where order_id=? and status='refunded'",oid))for(Object obj:JSON.parseArray(str(c.get("items_json")))){JSONObject line=JSON.parseObject(JSON.toJSONString(obj));if(line.getLongValue("id")==item)qty-=line.getLongValue("unshipped");}if(qty>0){String channel=str(i.get("channel"));s.jdbc().update("insert into shop_warehouse_allocation(order_id,product_id,warehouse_id,channel,reserved) values(?,?,1,?,?)",oid,pid,channel,qty);s.jdbc().update("update shop_warehouse_stock set reserved=reserved+? where warehouse_id=1 and product_id=? and channel=?",qty,pid,channel);}}
 }
 public List<Map<String,Object>> stocks(){return s.jdbc().queryForList("select x.*,w.name warehouse_name,p.name product_name,p.spec,(x.available+x.reserved+x.quarantine+x.damaged+x.campaign_reserved) physical_quantity from shop_warehouse_stock x join shop_warehouse w on w.id=x.warehouse_id join shop_product p on p.id=x.product_id order by w.priority,w.id,p.id,x.channel");}
 @Transactional public long available(long pid,String channel){ensure(pid);return s.jdbc().queryForObject("select coalesce(sum(x.available),0) from shop_warehouse_stock x join shop_warehouse w on w.id=x.warehouse_id where x.product_id=? and x.channel=? and w.enabled=1",Long.class,pid,channel);}
 public void plan(long oid,String channel,List<?> items){long chosen=0,required=0;List<Map<String,Object>> deliveries=s.jdbc().queryForList("select snapshot_json from shop_delivery_order where order_id=? and method='pickup'",oid);if(!deliveries.isEmpty())required=JSON.parseObject(str(deliveries.get(0).get("snapshot_json"))).getJSONObject("point").getLongValue("warehouseId");for(Map<String,Object> w:s.jdbc().queryForList("select id from shop_warehouse where enabled=1 and (?=0 or id=?) order by priority,id",required,required)){boolean enough=true;for(Object obj:items){JSONObject item=(JSONObject)obj;ensure(item.getLongValue("id"));if(s.jdbc().queryForObject("select coalesce(sum(available),0) from shop_warehouse_stock where warehouse_id=? and product_id=? and channel=?",Long.class,w.get("id"),item.get("id"),channel)<item.getLongValue("quantity")){enough=false;break;}}if(enough){chosen=number(w.get("id"));break;}}check(required==0||chosen==required,"自提门店仓库库存不足，请选择配送或其他门店");s.jdbc().update("insert into shop_warehouse_plan(order_id,warehouse_id) values(?,?)",oid,chosen);}
 public void change(long pid,long delta,String key,String note,String who){ensure(pid);if(key.startsWith("reserve_")){long oid=Long.parseLong(key.substring(8)),qty=-delta;Map<String,Object> o=s.one("select channel from shop_order where id=?",oid);String channel=str(o.get("channel"));long preferred=number(s.one("select warehouse_id from shop_warehouse_plan where order_id=?",oid).get("warehouse_id"));long remaining=qty;for(Map<String,Object> x:s.jdbc().queryForList("select x.* from shop_warehouse_stock x join shop_warehouse w on w.id=x.warehouse_id where x.product_id=? and x.channel=? and w.enabled=1 and (?=0 or x.warehouse_id=?) order by w.priority,w.id for update",pid,channel,preferred,preferred)){long n=Math.min(remaining,number(x.get("available"))),wid=number(x.get("warehouse_id"));if(n==0)continue;s.jdbc().update("update shop_warehouse_stock set available=available-?,reserved=reserved+? where warehouse_id=? and product_id=? and channel=?",n,n,wid,pid,channel);s.jdbc().update("insert into shop_warehouse_allocation(order_id,product_id,warehouse_id,channel,reserved) values(?,?,?,?,?)",oid,pid,wid,channel,n);movement(wid,pid,channel,"reserve",n,key,note,who);remaining-=n;if(remaining==0)break;}check(remaining==0,"当前渠道库存不足，不会自动借用另一渠道库存");return;}
 if(key.startsWith("release_")||key.startsWith("case_refund_")){long oid=key.startsWith("release_")?Long.parseLong(key.substring(8)):number(s.one("select order_id from shop_case where id=?",Long.parseLong(key.substring(12))).get("order_id"));long remaining=delta;for(Map<String,Object> a:s.jdbc().queryForList("select * from shop_warehouse_allocation where order_id=? and product_id=? order by warehouse_id for update",oid,pid)){long n=Math.min(remaining,number(a.get("reserved"))),wid=number(a.get("warehouse_id"));if(n==0)continue;s.jdbc().update("update shop_warehouse_allocation set reserved=reserved-?,released=released+? where order_id=? and product_id=? and warehouse_id=?",n,n,oid,pid,wid);s.jdbc().update("update shop_warehouse_stock set available=available+?,reserved=reserved-? where warehouse_id=? and product_id=? and channel=?",n,n,wid,pid,a.get("channel"));movement(wid,pid,str(a.get("channel")),"release",n,key,note,who);remaining-=n;if(remaining==0)break;}check(remaining==0,"原订单库存占用不一致，请核对后处理");return;}
 check(!key.startsWith("case_return_"),"退回商品应先登记待验收");String channel="C";if(key.startsWith("case_reship_"))channel=str(s.one("select o.channel from shop_case c join shop_order o on o.id=c.order_id where c.id=?",Long.parseLong(key.substring(12))).get("channel"));cell(1,pid,channel);Map<String,Object> x=s.one("select available from shop_warehouse_stock where warehouse_id=1 and product_id=? and channel=? for update",pid,channel);check(number(x.get("available"))+delta>=0,"默认仓该渠道库存不足，请先调拨");s.jdbc().update("update shop_warehouse_stock set available=available+? where warehouse_id=1 and product_id=? and channel=?",delta,pid,channel);movement(1,pid,channel,delta>0?"in":"out",Math.abs(delta),key,note,who);
 }
 public List<Map<String,Object>> allocations(long oid){return s.jdbc().queryForList("select a.*,w.name warehouse_name,p.name,p.spec from shop_warehouse_allocation a join shop_warehouse w on w.id=a.warehouse_id join shop_product p on p.id=a.product_id where a.order_id=?",oid);}
 public long ship(long oid,long wid,JSONArray items,String who){if(wid==0){for(Map<String,Object> w:s.jdbc().queryForList("select id from shop_warehouse where enabled=1 order by priority,id")){boolean enough=true;for(Object obj:items){JSONObject i=JSON.parseObject(JSON.toJSONString(obj));long pid=number(s.one("select product_id from shop_order_item where id=? and order_id=?",i.get("id"),oid).get("product_id"));if(s.jdbc().queryForObject("select coalesce(sum(reserved),0) from shop_warehouse_allocation where order_id=? and product_id=? and warehouse_id=?",Long.class,oid,pid,w.get("id"))<i.getLongValue("quantity")){enough=false;break;}}if(enough){wid=number(w.get("id"));break;}}}check(wid>0,"本单涉及多个仓库，请选择仓库分批发货");for(Object obj:items){JSONObject i=JSON.parseObject(JSON.toJSONString(obj));long pid=number(s.one("select product_id from shop_order_item where id=? and order_id=?",i.get("id"),oid).get("product_id")),qty=i.getLongValue("quantity");Map<String,Object> a=s.one("select * from shop_warehouse_allocation where order_id=? and product_id=? and warehouse_id=? for update",oid,pid,wid);check(number(a.get("reserved"))>=qty,"本仓预留数量不足，请调整分仓或发货数量");s.jdbc().update("update shop_warehouse_allocation set reserved=reserved-?,shipped=shipped+? where order_id=? and product_id=? and warehouse_id=?",qty,qty,oid,pid,wid);s.jdbc().update("update shop_warehouse_stock set reserved=reserved-? where warehouse_id=? and product_id=? and channel=?",qty,wid,pid,a.get("channel"));movement(wid,pid,str(a.get("channel")),"ship",qty,"order_"+oid,"按仓库实际发货",who);}return wid;}

 private void sync(long pid,long delta,String key,String note,String who){long total=s.jdbc().queryForObject("select coalesce(sum(available),0) from shop_warehouse_stock where product_id=?",Long.class,pid);s.jdbc().update("update shop_product set stock=?,version=version+1 where id=?",total,pid);s.jdbc().update("insert into shop_stock_log(product_id,delta,balance,request_key,note,operator_name) values(?,?,?,?,?,?)",pid,delta,total,key,note,who);}
 @Transactional public void transfer(JSONObject b,String who){long pid=integer(b.get("productId"),1,Long.MAX_VALUE,"请选择商品"),from=integer(b.get("from"),1,Long.MAX_VALUE,"请选择来源仓"),to=integer(b.get("to"),1,Long.MAX_VALUE,"请选择目标仓"),qty=integer(b.get("quantity"),1,100000000,"调拨数量应为正整数");String fc=b.getString("fromChannel"),tc=b.getString("toChannel"),key=str(b.get("requestKey")),note=str(b.get("note")).trim();check(Arrays.asList("C","B").contains(fc)&&Arrays.asList("C","B").contains(tc),"请选择零售或采购渠道");check(from!=to||!fc.equals(tc),"请选择不同的仓库或渠道");check(key.matches("[a-zA-Z0-9_-]{8,80}")&&note.length()>=2&&note.length()<=300,"请填写调拨原因");ensure(pid);if(s.jdbc().queryForObject("select count(*) from shop_stock_log where product_id=? and request_key=?",Long.class,pid,"transfer_"+key)>0)return;s.one("select id from shop_warehouse where id=? and enabled=1",to);cell(from,pid,fc);cell(to,pid,tc);Map<String,Object> source=s.one("select * from shop_warehouse_stock where warehouse_id=? and product_id=? and channel=? for update",from,pid,fc);check(number(source.get("available"))>=qty,"来源仓该渠道可售库存不足，占用库存不能直接调拨");s.jdbc().update("update shop_warehouse_stock set available=available-? where warehouse_id=? and product_id=? and channel=?",qty,from,pid,fc);s.jdbc().update("update shop_warehouse_stock set available=available+? where warehouse_id=? and product_id=? and channel=?",qty,to,pid,tc);movement(from,pid,fc,"transfer_out",qty,key,note,who);movement(to,pid,tc,"transfer_in",qty,key,note,who);sync(pid,0,"transfer_"+key,note,who);}
 @Transactional public void adjust(JSONObject b,String who){long pid=integer(b.get("productId"),1,Long.MAX_VALUE,"请选择商品"),wid=integer(b.get("warehouseId"),1,Long.MAX_VALUE,"请选择仓库"),delta=integer(b.get("delta"),-100000000,100000000,"数量应为整数");String channel=b.getString("channel"),key=str(b.get("requestKey")),note=str(b.get("note")).trim();check(Arrays.asList("C","B").contains(channel)&&delta!=0,"请选择渠道并填写增减件数");check(key.matches("[a-zA-Z0-9_-]{8,80}")&&note.length()>=2&&note.length()<=300,"请填写库存调整依据");ensure(pid);if(s.jdbc().queryForObject("select count(*) from shop_stock_log where product_id=? and request_key=?",Long.class,pid,"warehouse_"+key)>0)return;s.one("select id from shop_warehouse where id=? and enabled=1",wid);cell(wid,pid,channel);Map<String,Object> x=s.one("select * from shop_warehouse_stock where warehouse_id=? and product_id=? and channel=? for update",wid,pid,channel);check(number(x.get("available"))+delta>=0&&number(x.get("available"))+delta<=100000000,"调整后可售库存超出范围");s.jdbc().update("update shop_warehouse_stock set available=available+? where warehouse_id=? and product_id=? and channel=?",delta,wid,pid,channel);movement(wid,pid,channel,"adjust",delta,key,note,who);sync(pid,delta,"warehouse_"+key,note,who);}
 @Transactional public void warehouse(JSONObject b,String who){long id=b.getLongValue("id"),priority=integer(b.get("priority"),0,10000,"优先级应为0至10000");String name=str(b.get("name")).trim();check(name.length()>0&&name.length()<=80,"请填写仓库名称");if(id>0){s.one("select id from shop_warehouse where id=? for update",id);if(!b.getBooleanValue("enabled"))check(s.jdbc().queryForObject("select coalesce(sum(reserved+campaign_reserved),0) from shop_warehouse_stock where warehouse_id=?",Long.class,id)==0,"还有订单或活动占用库存，请先处理或结束活动");s.jdbc().update("update shop_warehouse set name=?,priority=?,enabled=? where id=?",name,priority,b.getBooleanValue("enabled"),id);}else s.jdbc().update("insert into shop_warehouse(name,priority,enabled) values(?,?,?)",name,priority,b.getBooleanValue("enabled"));s.event("warehouse",id,"保存仓库及发货优先级",who);}
 @Transactional public void reassign(long oid,JSONObject b,String who){s.one("select id from shop_order where id=? for update",oid);check(s.jdbc().queryForObject("select count(*) from shop_delivery_order where order_id=? and method='pickup'",Long.class,oid)==0,"自提订单已绑定取货门店，请在原门店仓备货");long pid=integer(b.get("productId"),1,Long.MAX_VALUE,"请选择商品"),from=b.getLongValue("from"),to=b.getLongValue("to"),qty=integer(b.get("quantity"),1,10000,"调整数量不正确");check(from!=to,"请选择不同的仓库");String key=str(b.get("requestKey"));check(key.matches("[a-zA-Z0-9_-]{8,80}"),"请刷新后重新调整分仓");ensure(pid);if(s.jdbc().queryForObject("select count(*) from shop_stock_log where product_id=? and request_key=?",Long.class,pid,"reassign_"+key)>0)return;s.one("select id from shop_warehouse where id=? and enabled=1",to);Map<String,Object> source=s.one("select * from shop_warehouse_allocation where order_id=? and product_id=? and warehouse_id=? for update",oid,pid,from);String channel=str(source.get("channel"));cell(to,pid,channel);Map<String,Object> target=s.one("select * from shop_warehouse_stock where warehouse_id=? and product_id=? and channel=? for update",to,pid,channel);check(number(source.get("reserved"))>=qty&&number(target.get("available"))>=qty,"原仓占用或目标仓可售数量不足");s.jdbc().update("update shop_warehouse_allocation set reserved=reserved-? where order_id=? and product_id=? and warehouse_id=?",qty,oid,pid,from);s.jdbc().update("insert into shop_warehouse_allocation(order_id,product_id,warehouse_id,channel,reserved) values(?,?,?,?,?) on duplicate key update reserved=reserved+values(reserved)",oid,pid,to,channel,qty);s.jdbc().update("update shop_warehouse_stock set available=available+?,reserved=reserved-? where warehouse_id=? and product_id=? and channel=?",qty,qty,from,pid,channel);s.jdbc().update("update shop_warehouse_stock set available=available-?,reserved=reserved+? where warehouse_id=? and product_id=? and channel=?",qty,qty,to,pid,channel);movement(from,pid,channel,"reassign_out",qty,"order_"+oid,"发货前调整分仓",who);movement(to,pid,channel,"reassign_in",qty,"order_"+oid,"发货前调整分仓",who);sync(pid,0,"reassign_"+key,"调整订单预留仓库",who);s.event("order",oid,"调整发货仓库",who);}
 public void returned(Map<String,Object> c,long wid,String who){if(wid==0)wid=1;s.one("select id from shop_warehouse where id=? and enabled=1",wid);String channel=str(s.one("select channel from shop_order where id=?",c.get("order_id")).get("channel"));for(Object obj:JSON.parseArray(str(c.get("items_json")))){JSONObject i=JSON.parseObject(JSON.toJSONString(obj));long pid=i.getLongValue("productId"),qty=i.getLongValue("quantity");ensure(pid);cell(wid,pid,channel);s.jdbc().update("insert into shop_warehouse_return(case_id,product_id,warehouse_id,channel,quantity) values(?,?,?,?,?)",c.get("id"),pid,wid,channel,qty);s.jdbc().update("update shop_warehouse_stock set quarantine=quarantine+? where warehouse_id=? and product_id=? and channel=?",qty,wid,pid,channel);movement(wid,pid,channel,"return_pending",qty,"case_"+c.get("id"),"退回商品登记待验收，尚不可销售",who);}}
 public void inspect(Map<String,Object> c,JSONObject b,String who){JSONArray rows=b.getJSONArray("inspection");check(rows!=null,"请填写各商品验收合格数量");List<Map<String,Object>> stored=s.jdbc().queryForList("select * from shop_warehouse_return where case_id=? for update",c.get("id"));check(rows.size()==stored.size(),"请逐项填写验收结果");Set<Long> seen=new HashSet<>();for(Object obj:rows){JSONObject row=JSON.parseObject(JSON.toJSONString(obj));long pid=row.getLongValue("productId");check(seen.add(pid),"验收商品不能重复");Map<String,Object> r=s.one("select * from shop_warehouse_return where case_id=? and product_id=? for update",c.get("id"),pid);check("pending".equals(r.get("status")),"该退回商品已经验收");long good=integer(row.get("accepted"),0,number(r.get("quantity")),"合格数量不能超过实际退回数量"),bad=number(r.get("quantity"))-good,wid=number(r.get("warehouse_id"));s.one("select id from shop_product where id=? for update",pid);s.jdbc().update("update shop_warehouse_stock set quarantine=quarantine-?,available=available+?,damaged=damaged+? where warehouse_id=? and product_id=? and channel=?",r.get("quantity"),good,bad,wid,pid,r.get("channel"));s.jdbc().update("update shop_warehouse_return set accepted=?,damaged=?,status='inspected' where case_id=? and product_id=?",good,bad,c.get("id"),pid);movement(wid,pid,str(r.get("channel")),"inspect",good,"case_"+c.get("id"),"合格转可售"+good+"件，不合格待处理"+bad+"件",who);sync(pid,good,"inspect_"+c.get("id"),"退回商品验收合格入可售库存",who);}}

 public void reship(Map<String,Object> c,long wid,String who){if(wid==0)wid=1;s.one("select id from shop_warehouse where id=? and enabled=1",wid);String channel=str(s.one("select channel from shop_order where id=?",c.get("order_id")).get("channel"));for(Object obj:JSON.parseArray(str(c.get("items_json")))){JSONObject i=JSON.parseObject(JSON.toJSONString(obj));long pid=i.getLongValue("productId"),qty=i.getLongValue("quantity");ensure(pid);Map<String,Object> x=s.one("select available from shop_warehouse_stock where warehouse_id=? and product_id=? and channel=? for update",wid,pid,channel);check(number(x.get("available"))>=qty,"换补发仓库该渠道可售不足，请调整仓库或调拨");s.jdbc().update("update shop_warehouse_stock set available=available-? where warehouse_id=? and product_id=? and channel=?",qty,wid,pid,channel);movement(wid,pid,channel,"replacement",qty,"case_"+c.get("id"),"换货或补发实际出库",who);sync(pid,-qty,"case_reship_"+c.get("id"),"换补发实际出库",who);}s.jdbc().update("update shop_case set replacement_warehouse_id=? where id=?",wid,c.get("id"));}

 @Transactional public void batch(JSONObject b,String who){JSONArray items=b.getJSONArray("items");check(items!=null&&!items.isEmpty()&&items.size()<=100,"每次批量调整1至100个商品");String key=str(b.get("requestKey"));check(key.matches("[a-zA-Z0-9_-]{8,55}"),"请重新预览批量调整");Set<Long> seen=new TreeSet<>();Map<Long,JSONObject> rows=new TreeMap<>();for(Object x:items){JSONObject line=JSON.parseObject(JSON.toJSONString(x));long pid=integer(line.get("productId"),1,Long.MAX_VALUE,"商品编号不正确");check(seen.add(pid),"商品不能重复");rows.put(pid,line);}for(Map.Entry<Long,JSONObject> entry:rows.entrySet()){long pid=entry.getKey();JSONObject line=entry.getValue();ensure(pid);String itemKey=key+"_"+pid;if(s.jdbc().queryForObject("select count(*) from shop_stock_log where product_id=? and request_key=?",Long.class,pid,"warehouse_"+itemKey)>0)continue;cell(b.getLongValue("warehouseId"),pid,b.getString("channel"));Map<String,Object> old=s.one("select available from shop_warehouse_stock where warehouse_id=? and product_id=? and channel=? for update",b.get("warehouseId"),pid,b.get("channel"));check(number(old.get("available"))==integer(line.get("expectedAvailable"),0,100000000,"请先预览现有库存"),"商品"+pid+"库存已改变，请重新预览整批清单");JSONObject one=new JSONObject(b);one.put("productId",pid);one.put("delta",line.get("delta"));one.put("requestKey",itemKey);adjust(one,who);}}
 @Transactional public void warning(JSONObject b,String who){long wid=b.getLongValue("warehouseId"),pid=b.getLongValue("productId"),qty=integer(b.get("quantity"),0,1000000,"预警数量应为0至1000000");String channel=b.getString("channel");s.one("select product_id from shop_warehouse_stock where warehouse_id=? and product_id=? and channel=?",wid,pid,channel);s.jdbc().update("update shop_warehouse_stock set warning_qty=? where warehouse_id=? and product_id=? and channel=?",qty,wid,pid,channel);s.event("product",pid,"设置仓库渠道库存预警数量",who);}
 @Transactional public void damaged(JSONObject b,String who){long wid=b.getLongValue("warehouseId"),pid=b.getLongValue("productId"),qty=integer(b.get("quantity"),1,1000000,"处理数量应为正整数");String channel=b.getString("channel"),action=b.getString("action"),note=str(b.get("note")).trim(),key=str(b.get("requestKey"));check(Arrays.asList("writeoff","recover").contains(action)&&note.length()>=2&&note.length()<=300&&key.matches("[a-zA-Z0-9_-]{8,80}"),"请选择处理方式并填写实际处理依据");ensure(pid);if(s.jdbc().queryForObject("select count(*) from shop_stock_log where product_id=? and request_key=?",Long.class,pid,"damaged_"+key)>0)return;Map<String,Object> cell=s.one("select damaged from shop_warehouse_stock where warehouse_id=? and product_id=? and channel=? for update",wid,pid,channel);check(number(cell.get("damaged"))>=qty,"处理数量超过不合格待处理数量");long recovered="recover".equals(action)?qty:0;s.jdbc().update("update shop_warehouse_stock set damaged=damaged-?,available=available+? where warehouse_id=? and product_id=? and channel=?",qty,recovered,wid,pid,channel);movement(wid,pid,channel,action,qty,key,note,who);sync(pid,recovered,"damaged_"+key,note,who);}
}
